CREATE TABLE IF NOT EXISTS organizations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,status VARCHAR(30) NOT NULL DEFAULT 'active',name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,INDEX(organization_id),FOREIGN KEY(organization_id) REFERENCES organizations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournaments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',name VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,season VARCHAR(30) NULL,description TEXT NULL,cover_path VARCHAR(255) NULL,logo_path VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,INDEX(project_id),FOREIGN KEY(project_id) REFERENCES projects(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournament_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL UNIQUE,version INT UNSIGNED NOT NULL DEFAULT 1,settings_json JSON NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournament_themes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL UNIQUE,primary_color CHAR(7) NOT NULL DEFAULT '#1261A0',secondary_color CHAR(7) NOT NULL DEFAULT '#0F7B52',accent_color CHAR(7) NOT NULL DEFAULT '#F4B942',light_enabled TINYINT(1) NOT NULL DEFAULT 1,dark_enabled TINYINT(1) NOT NULL DEFAULT 1,logo_path VARCHAR(255) NULL,cover_path VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,status VARCHAR(30) NOT NULL DEFAULT 'active',name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_key VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,permission_key VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS user_role_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,organization_id BIGINT UNSIGNED NULL,project_id BIGINT UNSIGNED NULL,tournament_id BIGINT UNSIGNED NULL,team_id BIGINT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS people (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,status VARCHAR(30) NOT NULL DEFAULT 'active',full_name VARCHAR(180) NOT NULL,public_name VARCHAR(120) NULL,person_type VARCHAR(30) NOT NULL DEFAULT 'athlete',birth_date DATE NULL,cpf_encrypted VARBINARY(512) NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL);
CREATE TABLE IF NOT EXISTS teams (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',name VARCHAR(160) NOT NULL,short_name VARCHAR(40) NULL,logo_path VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(project_id) REFERENCES projects(id),INDEX(project_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS team_tournament_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',group_name VARCHAR(80) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,UNIQUE KEY tournament_team(tournament_id,team_id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(team_id) REFERENCES teams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS team_memberships (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,team_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,role VARCHAR(40) NOT NULL DEFAULT 'staff',starts_at DATE NULL,ends_at DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(person_id) REFERENCES people(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NOT NULL,registration_type VARCHAR(30) NOT NULL DEFAULT 'athlete',status VARCHAR(30) NOT NULL DEFAULT 'pending',shirt_number VARCHAR(10) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(person_id) REFERENCES people(id),INDEX(tournament_id,team_id),INDEX(person_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(60) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED NULL,before_json JSON NULL,after_json JSON NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL,INDEX(entity_type,entity_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL,ip_address VARCHAR(45) NULL,success TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,INDEX(email,created_at),INDEX(ip_address,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS migrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,migration VARCHAR(190) NOT NULL UNIQUE,applied_at DATETIME NOT NULL);
